"""
tools/search_rounds_2809.py — 8 משפחות רעיונות שנבדקו ונפסלו ב-28/09/2026 (DECISIONS §63).
כל סבב מוגדר מראש, הרצה אחת, עלויות 0/0.5/1$. מריצים הכל: python search_rounds_2809.py   (מתוך tools/, קורא ../data/xauusd_m15.csv)
"""
import subprocess, sys, os, tempfile
ROUNDS = {}

ROUNDS['1 שבירה כושלת של שיא/שפל אתמול'] = '"""\nIDEA (new family: false break of yesterday\'s extreme = failed-auction fade). Pre-declared, run once:\n  Levels: previous UTC day\'s high (PDH) / low (PDL), from M15.\n  Short: 07:00–19:59 UTC, an M15 bar trades ≥1$ ABOVE PDH and CLOSES back BELOW PDH → sell at next bar open.\n  Long:  mirror at PDL.\n  Stop: sweep bar extreme ± 1$.  Target: 1.5 × risk.  Exit at 20:00 UTC.  Max 1 trade per side per day.\n  M15 execution, stop checked first. Costs: spread 0.77$ + slippage 0 / 0.5 / 1.0$ (entry and stop).\n  Pass rule: positive after 0.5$ slippage in BOTH train (<2025-07) and holdout, t ≥ 2. Otherwise → disqualified.\n"""\nimport numpy as np, pandas as pd, collections\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True).dt.tz_localize(None)\nT=m.t.values;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m)\nday=pd.to_datetime(T).normalize().values; hr=pd.to_datetime(T).hour.values\nud=np.unique(day); first={d:np.searchsorted(T,d) for d in ud}\nSPLIT=np.datetime64("2025-07-01"); K=4.5\ndef run(s):\n    out=[]\n    for j in range(1,len(ud)):\n        d0,d1=ud[j-1],ud[j]; a0=first[d0]; a1=first[d1]; a2=first[ud[j+1]] if j+1<len(ud) else n\n        if a1-a0<40: continue\n        pdh=H[a0:a1].max(); pdl=L[a0:a1].min(); done={1:False,-1:False}\n        i=a1\n        while i<a2-1:\n            if not (7<=hr[i]<20): i+=1; continue\n            sig=None\n            if not done[-1] and H[i]>=pdh+1 and C[i]<pdh: sig=(-1,H[i]+1)\n            elif not done[1] and L[i]<=pdl-1 and C[i]>pdl: sig=(1,L[i]-1)\n            if sig is None: i+=1; continue\n            d,stop=sig; done[d]=True\n            e=O[i+1]+d*s; risk=d*(e-stop)\n            if risk<=0.5: i+=1; continue\n            tgt=e+d*1.5*risk; res=None; k=i+1\n            while k<a2 and hr[k]<20:\n                if (L[k]<=stop) if d==1 else (H[k]>=stop): res=-risk-s; break\n                if (H[k]>=tgt) if d==1 else (L[k]<=tgt): res=1.5*risk; break\n                k+=1\n            if res is None: res=d*(C[min(k,n-1)-1]-e)\n            out.append((T[i],res-0.77)); i=k+1\n    return out\nmonths=len(ud)/30.4\nfor s in (0.0,0.5,1.0):\n    tr=run(s); v=np.array([x[1] for x in tr]); a=np.array([x[1] for x in tr if x[0]<SPLIT]); b=np.array([x[1] for x in tr if x[0]>=SPLIT]); y=collections.defaultdict(list)\n    for t,p in tr: y[str(t)[:4]].append(p)\n    t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n    print(f"slip {s}: N={len(v)} ({len(v)/months:.0f}/mo) win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr {v.sum()*K/months:+.0f}₪/mo t={t_:+.2f} | train {a.mean()*K:+.1f} hold {b.mean()*K:+.1f} | yrs {[round(float(np.mean(x))*K,1) for k,x in sorted(y.items())]}")\n'

ROUNDS['2 היפוך הסשן האסייתי'] = 'import numpy as np, pandas as pd, collections\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True).dt.tz_localize(None)\nT=m.t.values;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m)\nday=pd.to_datetime(T).normalize().values; SPLIT=np.datetime64("2025-07-01"); K=4.5\ndef run(s, side):   # side=-1 fade (pre-declared), +1 follow (shown only as the mirror, not selectable)\n    out=[]\n    for dd in np.unique(day):\n        i0=np.searchsorted(T,dd); i7=np.searchsorted(T,dd+np.timedelta64(7,"h")); i20=np.searchsorted(T,dd+np.timedelta64(20,"h"))\n        if i7-i0<20 or i20-i7<40: continue\n        mv=C[i7-1]-O[i0]\n        if abs(mv)<3: continue\n        d=side*int(np.sign(mv)); e=O[i7]+d*s; stop=e-d*1.5*abs(mv); res=None\n        for k in range(i7,i20):\n            if (L[k]<=stop) if d==1 else (H[k]>=stop): res=-1.5*abs(mv)-s; break\n        if res is None: res=d*(C[i20-1]-e)\n        out.append((dd,res-0.77,d))\n    return out\nmonths=len(np.unique(day))/30.4\nfor side,lab in ((-1,"FADE Asia (the hypothesis)"),(1,"follow Asia (mirror, for reference)")):\n    print(lab)\n    for s in (0.0,0.5,1.0):\n        tr=run(s,side); v=np.array([x[1] for x in tr]); a=np.array([x[1] for x in tr if x[0]<SPLIT]); b=np.array([x[1] for x in tr if x[0]>=SPLIT]); y=collections.defaultdict(list)\n        for t,p,_ in tr: y[str(t)[:4]].append(p)\n        Lg=[x[1] for x in tr if x[2]==1]; Sh=[x[1] for x in tr if x[2]==-1]\n        t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n        print(f"  slip {s}: N={len(v)} ({len(v)/months:.0f}/mo) win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr {v.sum()*K/months:+.0f}₪/mo t={t_:+.2f} | train {a.mean()*K:+.1f} hold {b.mean()*K:+.1f} | long {np.mean(Lg)*K:+.1f} short {np.mean(Sh)*K:+.1f} | yrs {[round(float(np.mean(x))*K,1) for k,x in sorted(y.items())]}")\n'

ROUNDS['3 סשן ארה"ב → לילה'] = '"""\nHypothesis (new family: overnight hand-off West → East). Pre-declared, run once:\n  Signal: US session move = NY 09:30 open → NY 16:00 close (DST-correct). Only if |move| ≥ 5$.\n  Direction: CONTINUE the US move (lesson from the last round: gold flows persist, they don\'t revert).\n  Entry: market at NY 16:00 (≈23:00 Israel) — can be done before sleep.\n  Stop: 1.0 × |US move|.  No target.  Exit: 07:00 UTC next morning (≈10:00 Israel, awake).\n  Costs: spread 0.77$ + OVERNIGHT FUNDING (held through 00:00 Israel): 0.0319% buy / 0.0120% sell of price\n         + slippage 0 / 0.5 / 1.0$.\n  Pass: positive after 0.5$ in train AND holdout, t ≥ 2. Otherwise disqualified.\n"""\nimport numpy as np, pandas as pd, collections\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True)\nT=m.t.values;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m)\nny=m.t.dt.tz_convert("America/New_York"); nyd=ny.dt.date.values; nyhm=(ny.dt.hour*100+ny.dt.minute).values\nidx={}\nfor i,(d,hm) in enumerate(zip(nyd,nyhm)): idx[(d,hm)]=i\nSPLIT=pd.Timestamp("2025-07-01",tz="UTC").to_datetime64(); K=4.5\nutc=m.t.dt.tz_convert("UTC")\ndef run(s):\n    out=[]\n    for d in sorted(set(nyd)):\n        i0=idx.get((d,930)); i1=idx.get((d,1545))\n        if i0 is None or i1 is None: continue\n        mv=C[i1]-O[i0]\n        if abs(mv)<5: continue\n        dr=int(np.sign(mv)); ie=i1+1\n        if ie>=n: continue\n        # exit: first bar at/after 07:00 UTC of the next UTC day\n        tnext=(pd.Timestamp(T[ie]).normalize()+pd.Timedelta(days=1 if pd.Timestamp(T[ie]).hour>=7 else 0)+pd.Timedelta(hours=7)).to_datetime64()\n        ix=np.searchsorted(T,tnext)\n        if ix>=n or (T[ix]-T[ie])>np.timedelta64(30,"h"): continue\n        e=O[ie]+dr*s; stop=e-dr*abs(mv); res=None\n        for k in range(ie,ix):\n            if (L[k]<=stop) if dr==1 else (H[k]>=stop): res=-abs(mv)-s; break\n        if res is None: res=dr*(O[ix]-e)\n        fund=e*(0.000319 if dr==1 else 0.000120)\n        out.append((T[ie],res-0.77-fund,dr))\n    return out\nmonths=len(set(nyd))/30.4\nfor s in (0.0,0.5,1.0):\n    tr=run(s); v=np.array([x[1] for x in tr]); a=np.array([x[1] for x in tr if x[0]<SPLIT]); b=np.array([x[1] for x in tr if x[0]>=SPLIT]); y=collections.defaultdict(list)\n    for t,p,_ in tr: y[str(t)[:4]].append(p)\n    Lg=[x[1] for x in tr if x[2]==1]; Sh=[x[1] for x in tr if x[2]==-1]\n    t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n    print(f"slip {s}: N={len(v)} ({len(v)/months:.0f}/mo) win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr {v.sum()*K/months:+.0f}₪/mo t={t_:+.2f} | train {a.mean()*K:+.1f} hold {b.mean()*K:+.1f} | long {np.mean(Lg)*K:+.1f} short {np.mean(Sh)*K:+.1f} | yrs {[round(float(np.mean(x))*K,1) for k,x in sorted(y.items())]}")\n'

ROUNDS['4 שישי נגד השבוע'] = '"""\nHypothesis (new family: weekly position-squaring). Pre-declared, run once:\n  Week move = first bar of the week (Sunday/Monday reopen) → Friday 12:00 New York. Only if |move| ≥ 0.5% of price.\n  Entry: Friday 12:00 NY, AGAINST the week\'s move.\n  Stop: 0.5% of price.  No target.  Exit: Friday\'s last bar before the weekend close.\n  Costs: 0.77$ + slippage 0 / 0.5 / 1.0$. No overnight funding (closed before the weekend).\n  Pass: positive after 0.5$ in train AND holdout, t ≥ 2.\n"""\nimport numpy as np, pandas as pd, collections\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True)\nT=m.t.values;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m)\nny=m.t.dt.tz_convert("America/New_York"); wd=ny.dt.dayofweek.values; hm=(ny.dt.hour*100+ny.dt.minute).values\ngap=np.r_[999,np.diff(T).astype("timedelta64[h]").astype(int)]\nweek_start=np.where(gap>=24)[0]                    # first bar after the weekend\nSPLIT=np.datetime64("2025-07-01"); K=4.5\ndef run(s,side=-1):\n    out=[]\n    for j in range(len(week_start)):\n        a=week_start[j]; z=week_start[j+1] if j+1<len(week_start) else n\n        fri=[i for i in range(a,z) if wd[i]==4]\n        if not fri: continue\n        e_i=[i for i in fri if hm[i]>=1200]\n        if not e_i: continue\n        ie=e_i[0]; last=fri[-1]\n        mv=C[ie-1]-O[a]\n        if abs(mv)<0.005*C[ie-1]: continue\n        d=side*int(np.sign(mv)); e=O[ie]+d*s; sd=0.005*e; stop=e-d*sd; res=None\n        for k in range(ie,last+1):\n            if (L[k]<=stop) if d==1 else (H[k]>=stop): res=-sd-s; break\n        if res is None: res=d*(C[last]-e)\n        out.append((T[ie],res-0.77,d))\n    return out\nfor s in (0.0,0.5,1.0):\n    tr=run(s); v=np.array([x[1] for x in tr]); a=np.array([x[1] for x in tr if x[0]<SPLIT]); b=np.array([x[1] for x in tr if x[0]>=SPLIT]); y=collections.defaultdict(list)\n    for t,p,_ in tr: y[str(t)[:4]].append(p)\n    Lg=[x[1] for x in tr if x[2]==1]; Sh=[x[1] for x in tr if x[2]==-1]\n    t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n    print(f"slip {s}: N={len(v)} win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr t={t_:+.2f} | train {a.mean()*K:+.1f} (N={len(a)}) hold {b.mean()*K:+.1f} (N={len(b)}) | long {np.mean(Lg)*K:+.1f} short {np.mean(Sh)*K:+.1f} | yrs {[round(float(np.mean(x))*K,1) for k,x in sorted(y.items())]}")\n'

ROUNDS['5-7 FOMC / פקיעת אופציות / סוף חודש'] = 'import numpy as np, pandas as pd, datetime as dt\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True)\nT=m.t;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m); K=4.5\ndef at(ts):  # first bar at/after a tz-aware timestamp\n    i=T.searchsorted(ts); return i if i<n else None\ndef trade(ie,ix,d,stopd,s,tgt=None):\n    e=O[ie]+d*s; stop=e-d*stopd\n    for k in range(ie,ix):\n        if (L[k]<=stop) if d==1 else (H[k]>=stop): return -stopd-s-0.77\n        if tgt is not None and ((H[k]>=tgt) if d==1 else (L[k]<=tgt)): return d*(tgt-e)-0.77\n    return d*(C[ix-1]-e)-0.77\ndef rep(name,res):\n    for s,v in res.items():\n        v=np.array([x[1] for x in v]); t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n        print(f"  slip {s}: N={len(v)} win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr t={t_:+.2f}")\n    v=res[0.5]; a=[x[1] for x in v if x[0]<pd.Timestamp("2025-07-01",tz="UTC")]; b=[x[1] for x in v if x[0]>=pd.Timestamp("2025-07-01",tz="UTC")]\n    print(f"  (slip 0.5) train {np.mean(a)*K:+.1f}₪ N={len(a)} | holdout {np.mean(b)*K:+.1f}₪ N={len(b)}")\nNY="America/New_York"; LON="Europe/London"\n# 1) PRE-FOMC: long from 14:00 ET day before → 13:45 ET decision day. Stop 1% of price.\nfomc=["2023-11-01","2023-12-13","2024-01-31","2024-03-20","2024-05-01","2024-06-12","2024-07-31","2024-09-18","2024-11-07","2024-12-18",\n      "2025-01-29","2025-03-19","2025-05-07","2025-06-18","2025-07-30","2025-09-17","2025-10-29","2025-12-10",\n      "2026-01-28","2026-03-18","2026-04-29","2026-06-17","2026-07-29","2026-09-16"]\nres={0.0:[],0.5:[],1.0:[]}\nfor d in fomc:\n    D=pd.Timestamp(d,tz=NY); ie=at((D-pd.Timedelta(days=1)).replace(hour=14)); ix=at(D.replace(hour=13,minute=45))\n    if ie is None or ix is None: continue\n    for s in res: res[s].append((T.iat[ie],trade(ie,ix,1,0.01*O[ie],s)))\nprint("1) PRE-FOMC drift — LONG 24h before the decision (hypothesis: markets drift up into FOMC):"); rep("fomc",res)\n# 2) OPTIONS EXPIRY pinning: 4th-last business day of each month. 08:30 ET → 13:30 ET, trade toward the nearest 50$ level if ≥5$ away; target = the level, stop = same distance.\nres={0.0:[],0.5:[],1.0:[]}\nfor mo in pd.date_range("2023-10-01","2026-09-01",freq="MS"):\n    bd=pd.bdate_range(mo,mo+pd.offsets.MonthEnd(0)); ex=bd[-4]\n    D=pd.Timestamp(ex.date(),tz=NY); ie=at(D.replace(hour=8,minute=30)); ix=at(D.replace(hour=13,minute=30))\n    if ie is None or ix is None or ix<=ie: continue\n    p=O[ie]; lvl=round(p/50)*50; dist=abs(lvl-p)\n    if dist<5: continue\n    d=1 if lvl>p else -1\n    for s in res: res[s].append((T.iat[ie],trade(ie,ix,d,dist,s,tgt=lvl)))\nprint("2) Gold options expiry — price pulled to nearest 50$ level (08:30→13:30 ET):"); rep("opex",res)\n# 3) MONTH-END rebalancing: last business day, 13:00→16:15 London, AGAINST the month\'s move if |month| ≥ 2%. Stop 0.5%.\nres={0.0:[],0.5:[],1.0:[]}\nfor mo in pd.date_range("2023-10-01","2026-08-01",freq="MS"):\n    bd=pd.bdate_range(mo,mo+pd.offsets.MonthEnd(0)); last=bd[-1]\n    D=pd.Timestamp(last.date(),tz=LON); ie=at(D.replace(hour=13)); ix=at(D.replace(hour=16,minute=15)); i0=at(pd.Timestamp(mo,tz="UTC"))\n    if None in (ie,ix,i0) or ix<=ie: continue\n    mv=O[ie]/O[i0]-1\n    if abs(mv)<0.02: continue\n    d=-int(np.sign(mv))\n    for s in res: res[s].append((T.iat[ie],trade(ie,ix,d,0.005*O[ie],s)))\nprint("3) Month-end rebalancing — against a ≥2% month, 13:00→16:15 London:"); rep("monthend",res)\n'

ROUNDS['8 שעה ראשונה של COMEX'] = '"""\nHypothesis (time-anchored flow, COMEX open). Pre-declared, run once:\n  First hour = 08:15–09:14 New York (COMEX open ≈08:20). Signal = its direction (close 09:14 − open 08:15), only if |move| ≥ 3$.\n  Entry: 09:15 NY, SAME direction (lesson: flows continue).\n  Stop: the opposite side of the first-hour range.  No target.  Exit: 13:30 NY (COMEX close).\n  Costs 0.77$ + slippage 0 / 0.5 / 1.0$. Pass: positive after 0.5$ in train AND holdout, t ≥ 2.\n"""\nimport numpy as np, pandas as pd, collections\nm=pd.read_csv("../data/xauusd_m15.csv"); m["t"]=pd.to_datetime(m["timestamp"],utc=True)\nT=m.t.values;O=m.open.values;H=m.high.values;L=m.low.values;C=m.close.values;n=len(m)\nny=m.t.dt.tz_convert("America/New_York"); nyd=ny.dt.date.values; hm=(ny.dt.hour*100+ny.dt.minute).values\nidx={(d,x):i for i,(d,x) in enumerate(zip(nyd,hm))}\nSPLIT=np.datetime64("2025-07-01"); K=4.5\ndef run(s):\n    out=[]\n    for d in sorted(set(nyd)):\n        a=idx.get((d,815)); b=idx.get((d,900)); e_i=idx.get((d,915)); x=idx.get((d,1315))\n        if None in (a,b,e_i,x): continue\n        mv=C[b]-O[a]\n        if abs(mv)<3: continue\n        dr=int(np.sign(mv)); hi=H[a:b+1].max(); lo=L[a:b+1].min()\n        e=O[e_i]+dr*s; stop=lo if dr==1 else hi; risk=dr*(e-stop)\n        if risk<=0: continue\n        res=None\n        for k in range(e_i,x+1):\n            if (L[k]<=stop) if dr==1 else (H[k]>=stop): res=-risk-s; break\n        if res is None: res=dr*(C[x]-e)\n        out.append((T[e_i],res-0.77,dr))\n    return out\nmonths=len(set(nyd))/30.4\nfor s in (0.0,0.5,1.0):\n    tr=run(s); v=np.array([x[1] for x in tr]); a=np.array([x[1] for x in tr if x[0]<SPLIT]); b=np.array([x[1] for x in tr if x[0]>=SPLIT]); y=collections.defaultdict(list)\n    for t,p,_ in tr: y[str(t)[:4]].append(p)\n    Lg=[x[1] for x in tr if x[2]==1]; Sh=[x[1] for x in tr if x[2]==-1]\n    t_=v.mean()/(v.std(ddof=1)/np.sqrt(len(v)))\n    print(f"slip {s}: N={len(v)} ({len(v)/months:.0f}/mo) win {100*(v>0).mean():.0f}% {v.mean()*K:+.1f}₪/tr {v.sum()*K/months:+.0f}₪/mo t={t_:+.2f} | train {a.mean()*K:+.1f} hold {b.mean()*K:+.1f} | long {np.mean(Lg)*K:+.1f} short {np.mean(Sh)*K:+.1f} | yrs {[round(float(np.mean(x))*K,1) for k,x in sorted(y.items())]}")\n'

if __name__ == "__main__":
    for title, src in ROUNDS.items():
        print("\n" + "=" * 70 + "\n" + title + "\n" + "=" * 70, flush=True)
        exec(compile(src, title, "exec"), {"__name__": "round"})
